/* data/cs-c/cs-12-08.js - GENERATED by tools/build.py from data/cs/cs-12-08.json. Questions are the board's; answers are our own words. Do not edit. */
(window.CS_C = window.CS_C || {})["cs-12-08"] = [{"id":"cs-12-08-01","kind":"short","q":"What is microcontroller ?","marks":3,"src":["Guide ch.8 Introduction to Microcontroller, Q.1"],"model":[{"t":"A microcontroller is a single chip computer: a CPU, memory (ROM and RAM), input and output ports and timers on one chip.","m":1},{"t":"It is made to control a machine or a device.","m":1},{"t":"Examples: Intel 8051, 8052, 8048. It is used in washing machines, remote controls and so on.","m":1}]},{"id":"cs-12-08-02","kind":"short","q":"What are advantages of microcontroller over standalone microprocessor ?","marks":4,"src":["Guide ch.8 Introduction to Microcontroller, Q.2"],"model":[{"t":"Memory, ports and timers are inside the chip, so no outside chips are needed.","m":1},{"t":"The system is smaller and cheaper, and the circuit board is simpler.","m":1},{"t":"It uses less power and is more reliable, as there are fewer connections.","m":1},{"t":"The design and the testing are quicker.","m":1}]},{"id":"cs-12-08-03","kind":"short","q":"Why microcontrollers are not used to implement general purpose personal computers ?","marks":4,"src":["Guide ch.8 Introduction to Microcontroller, Q.3"],"model":[{"t":"A microcontroller has very little memory on the chip (for example 4 KB of ROM and 128 bytes of RAM in the 8051).","m":1},{"t":"Its CPU is slow and less powerful, and it has a small address space.","m":1},{"t":"It has no support for large memory, disks, display cards and other fast peripherals.","m":1},{"t":"It is designed for one fixed control job, while a personal computer must run many different programs.","m":1}]},{"id":"cs-12-08-04","kind":"prog","q":"Draw diagram for 8051 architecture.","marks":5,"src":["Guide ch.8 Introduction to Microcontroller, Q.4"],"model":[{"t":"The CPU is shown with the accumulator, register B, the ALU, the program status word, the stack pointer and the data pointer.","m":1},{"t":"The on-chip memory is shown: 4 KB program ROM and 128 bytes data RAM.","m":1},{"t":"The four 8-bit I/O ports P0, P1, P2, P3, the serial port, and the two timers are shown.","m":1},{"t":"The interrupt control and the oscillator and timing circuit are shown.","m":1},{"t":"The blocks are joined by the internal bus and the diagram is neat.","m":1}],"code":"  +----------------------------------------------------------+\n  | 8051                                                     |\n  |  Interrupt control   Timer 0   Timer 1   Serial port     |\n  |  4 KB ROM            128 byte RAM                        |\n  |  CPU: ALU, accumulator A, register B, PSW, SP, DPTR, PC  |\n  |  Oscillator and timing                                   |\n  |  Port 0   Port 1   Port 2   Port 3     (8 bits each)     |\n  +----------------------------------------------------------+"},{"id":"cs-12-08-05","kind":"short","q":"What are major features of 8051","marks":5,"src":["Guide ch.8 Introduction to Microcontroller, Q.5"],"model":[{"t":"An 8-bit CPU with an accumulator A and a register B, working at 12 MHz.","m":1},{"t":"On-chip memory: 4 KB of ROM (program) and 128 bytes of RAM (data).","m":1},{"t":"Four 8-bit input and output ports, P0 to P3 (32 lines), and a full duplex serial port.","m":1},{"t":"Two 16-bit timers and counters, and five interrupts (two external, two timer and one serial).","m":1},{"t":"It can address 64 KB of outside program memory and 64 KB of outside data memory, and it has a bit-addressable area (Boolean processor).","m":1}]},{"id":"cs-12-08-06","kind":"prog","q":"Explain memory map of 8051.","marks":5,"src":["Guide ch.8 Introduction to Microcontroller, Q.6"],"model":[{"t":"The 8051 has separate program memory and data memory.","m":1},{"t":"Program memory: the first 4 KB (0000H to 0FFFH) is inside the chip; more can be added outside up to 64 KB.","m":1},{"t":"Internal data RAM of 128 bytes (00H to 7FH): four register banks of R0 to R7 at 00H to 1FH.","m":1},{"t":"A bit-addressable area at 20H to 2FH, and general purpose (scratch pad) RAM at 30H to 7FH.","m":1},{"t":"The special function registers (SFR) such as A, B, PSW, SP, DPTR and the ports are at 80H to FFH.","m":1}],"code":"  Internal data memory            Program memory\n  FFH +---------------------+    FFFFH +--------------+\n      | Special function    |          | external     |\n  80H | registers (SFR)     |    1000H +--------------+\n  7FH +---------------------+          | internal 4 KB|\n      | scratch pad RAM     |    0000H +--------------+\n  30H +---------------------+\n  2FH | bit addressable     |\n  20H +---------------------+\n  1FH | register banks 0-3  |\n  00H +---------------------+"},{"id":"cs-12-08-07","kind":"prog","q":"Compare 8051, 8052 and 8048 microcontrollers.","marks":5,"src":["Guide ch.8 Introduction to Microcontroller, Q.7"],"model":[{"t":"8051: 4 KB ROM, 128 bytes RAM, two 16-bit timers, 5 interrupts, 32 I/O lines.","m":1},{"t":"8052: 8 KB ROM, 256 bytes RAM, three 16-bit timers, 6 interrupts, 32 I/O lines.","m":1},{"t":"8048: 1 KB ROM, 64 bytes RAM, one 8-bit timer, 27 I/O lines; it is the older family.","m":1},{"t":"The 8051 and 8052 have a full duplex serial port and a Boolean processor; the 8048 has no serial port.","m":1},{"t":"The 8052 is an improved 8051 and runs its programs; the 8048 uses a different instruction set.","m":1}],"code":"                8051        8052        8048\n  ROM           4 KB        8 KB        1 KB\n  RAM           128 byte    256 byte    64 byte\n  Timers        2 (16 bit)  3 (16 bit)  1 (8 bit)\n  I/O lines     32          32          27\n  Serial port   yes         yes         no"},{"id":"cs-12-08-08","kind":"prog","q":"Draw memory map for 8048.","marks":4,"src":["Guide ch.8 Introduction to Microcontroller, Q.8"],"model":[{"t":"The 8048 has separate program memory and data memory.","m":1},{"t":"Program memory: 1 KB inside the chip (000H to 3FFH), and it can be extended outside up to 4 KB.","m":1},{"t":"Data memory: 64 bytes of RAM inside the chip (00H to 3FH).","m":1},{"t":"In the RAM: the register bank 0 at 00H to 07H, the 8-level stack at 08H to 17H, the register bank 1 at 18H to 1FH, and general purpose RAM at 20H to 3FH.","m":1}],"code":"  Data RAM (64 bytes)           Program memory\n  3FH +----------------+        FFFH +-------------+\n      | general RAM    |             | external    |\n  20H +----------------+        400H +-------------+\n  1FH | register bank 1|             | internal 1KB|\n  18H +----------------+        000H +-------------+\n  17H | stack (8 level)|\n  08H +----------------+\n  07H | register bank 0|\n  00H +----------------+"},{"id":"cs-12-08-09","kind":"short","q":"Write applications of microcontrollers.","marks":4,"src":["Guide ch.8 Introduction to Microcontroller, Q.9"],"model":[{"t":"Home: washing machines, microwave ovens, air conditioners, TV and music system remotes.","m":1},{"t":"Vehicles: engine control, anti-lock brakes, dashboard displays.","m":1},{"t":"Industry and office: process control, robots, printers, photocopiers, card readers, ATMs.","m":1},{"t":"Medical and others: digital thermometers, blood pressure monitors, mobile phones, toys, security systems.","m":1}]},{"id":"cs-12-08-m10a","kind":"mcq","q":"8051 is a ............. bit microcontroller.","marks":1,"src":["Guide ch.8 Introduction to Microcontroller, Q.10(a)"],"options":["2","4","8","16"],"ans":2,"why":"The 8051 has an 8-bit CPU and an 8-bit data bus, so it is an 8-bit microcontroller."},{"id":"cs-12-08-m10b","kind":"mcq","q":"8051 has ............. RAM.","marks":1,"src":["Guide ch.8 Introduction to Microcontroller, Q.10(b)"],"options":["128 x 8","4k x 4","256 x 8","4 k x 8"],"ans":0,"why":"The 8051 has 128 bytes of on-chip RAM, written 128 x 8."},{"id":"cs-12-08-m10c","kind":"mcq","q":"8051 has ............. ROM.","marks":1,"src":["Guide ch.8 Introduction to Microcontroller, Q.10(c)"],"options":["128 x 8","4 k x 8","256 x 8","4k x 4"],"ans":1,"why":"The 8051 has 4 KB of on-chip program ROM, written 4k x 8."},{"id":"cs-12-08-m10d","kind":"mcq","q":"8052 has ............. ROM.","marks":1,"src":["Guide ch.8 Introduction to Microcontroller, Q.10(d)"],"options":["8 k x 8","4 k x 8","128 x 8","256 x 8"],"ans":0,"why":"The 8052 is the bigger member of the family: 8 KB of ROM (8k x 8), 256 bytes of RAM."},{"id":"cs-12-08-p901","kind":"mcq","q":"The internal ROM of 8051 is ..........","marks":1,"src":["HSC March 2023 Paper II, Q.1A(d)"],"options":["2 KB","8 KB","4 KB","16 KB"],"ans":2,"why":"The 8051 has 4 KB of internal ROM (the 8052 has 8 KB)."},{"id":"cs-12-08-p902","kind":"short","q":"Compare Microcontroller with Microprocessor.","marks":3,"src":["HSC March 2022 Paper II, Q.2A(a)"],"model":[{"t":"Parts: a microprocessor is only the CPU, and needs outside memory and I/O chips. A microcontroller has the CPU, RAM, ROM, I/O ports, timers and serial port on one chip.","m":1},{"t":"Use: a microprocessor is for general purpose computers (PC). A microcontroller is for one dedicated job in a device (washing machine, remote control).","m":1},{"t":"Size and cost: a system with a microcontroller is smaller, cheaper and uses less power. A microprocessor system is bigger and costlier, but faster and more powerful.","m":1}]},{"id":"cs-12-08-p903","kind":"short","q":"Explain any four advantages and four applications of Microcontroller.","marks":4,"src":["HSC March 2022 Paper II, Q.4B(a)"],"model":[{"t":"Advantages: a complete computer on one chip (CPU, memory and I/O inside), so the circuit board is small.","m":1},{"t":"Advantages: low cost and low power use; fewer outside chips mean fewer faults and quick design.","m":1},{"t":"Applications: home appliances (washing machine, microwave oven), toys and remote controls.","m":1},{"t":"Applications: automobiles (engine control, ABS), mobile phones, printers, and medical and industrial control equipment.","m":1}]},{"id":"cs-12-08-p904","kind":"short","q":"Write ROM and RAM size of the following Microcontrollers :\ni) 8050\nii) 8051\niii) 8052","marks":3,"src":["HSC March 2023 Paper II, Q.3A(a)"],"model":[{"t":"8050 is printed in the paper. The guide gives no figure for a device of that name (the family is 8031, 8051 and 8052), so it is probably a misprint; ask your teacher.","m":1},{"t":"8051: ROM 4 KB and RAM 128 bytes.","m":1},{"t":"8052: ROM 8 KB and RAM 256 bytes.","m":1}]},{"id":"cs-12-08-p905","kind":"short","q":"Define Microcontroller. State any 4 advantages of same over microprocessor based system.","marks":3,"src":["HSC March 2024 Paper II, Q.1B(c)"],"model":[{"t":"A microcontroller is a single chip that has a CPU, memory (RAM and ROM), I/O ports, timers and a serial port. It is a small computer for control jobs.","m":1},{"t":"Advantages over a microprocessor system: smaller size and a simple circuit, because memory and I/O are inside the chip.","m":1},{"t":"Lower cost, lower power use, higher reliability, and it is easy to design and quick to produce.","m":1}]}];
